-- title:   Pip's Peak (lesson 7)
-- author:  TIC-80 Platformer Course
-- desc:    Tile collision
-- script:  lua

-- == Constants ==
local BTN_LEFT = 2
local BTN_RIGHT = 3
local BTN_A = 4   -- A is the Z key
local ANIM_IDLE = {256, 257}
local ANIM_RUN = {258, 259, 260, 261}
local SPR_JUMP, SPR_FALL = 262, 263

local F_SOLID = 0       -- sprite flag 0 marks tiles you can stand on

local GRAVITY = 0.25
local JUMP_SPEED = -4
local JUMP_CUT = -1.5
local MAX_FALL = 4
local START_X, START_Y = 16, 80

-- == State ==
-- x, y is the top-left corner of Pip's hitbox, a 6x8 box (the sprite is
-- drawn one pixel to the left so the box sits in the middle of it)
player = {
  x = START_X, y = START_Y, w = 6,
  h = 8, vy = 0, flip = 0,
  moving = false, ground = false,
  jumping = false
}
t = 0

-- == Collision ==
-- Is the map tile at cell (tx, ty) solid?
function solid_at(tx, ty)
  return fget(mget(tx, ty), F_SOLID)
end

-- Does a w x h box at pixel (x, y) overlap any solid tile?
function box_hits(x, y, w, h)
  for ty = y // 8, (y + h - 1) // 8 do
    for tx = x // 8,
        (x + w - 1) // 8 do
      if solid_at(tx, ty) then
        return true
      end
    end
  end
  return false
end

-- Move e sideways by dx; if that runs into a wall, push it back out.
-- Returns true when it hit something.
function move_x(e, dx)
  e.x = e.x + dx
  if not box_hits(e.x, e.y, e.w, e.h)
  then
    return false
  end
  if dx > 0 then
    e.x =
      (e.x + e.w - 1) // 8 * 8 - e.w   -- just left of the wall
  else
    e.x = e.x // 8 * 8 + 8                  -- just right of the wall
  end
  return true
end

-- Move e up or down by dy, the same way.
function move_y(e, dy)
  e.y = e.y + dy
  if not box_hits(e.x, e.y, e.w, e.h)
  then
    return false
  end
  if dy > 0 then
    e.y =
      (e.y + e.h - 1) // 8 * 8 - e.h   -- standing on the tile
  else
    e.y = e.y // 8 * 8 + 8                  -- head against the ceiling
  end
  return true
end

-- == Animation ==
function anim_frame(frames, speed)
  return
    frames[(t // speed) % #frames + 1]
end

-- == Player ==
function update_player(p)
  local dx = 0
  p.moving = false
  if btn(BTN_LEFT) then
    dx = -1
    p.flip = 1
    p.moving = true
  end
  if btn(BTN_RIGHT) then
    dx = 1
    p.flip = 0
    p.moving = true
  end
  move_x(p, dx)
  p.x = math.max(0,
      math.min(p.x, 240 - p.w))   -- stay on the screen

  if btnp(BTN_A) and p.ground then
    p.vy = JUMP_SPEED
    p.jumping = true
  end
  if p.jumping and not btn(BTN_A)
      and p.vy < JUMP_CUT then
    p.vy = JUMP_CUT
  end
  if p.vy >= 0 then
    p.jumping = false
  end

  -- move one axis at a time: sideways first (above), then up or down
  p.vy =
    math.min(p.vy + GRAVITY, MAX_FALL)
  if move_y(p, p.vy) then p.vy = 0 end
  -- standing on something? look one pixel below the feet
  p.ground =
    box_hits(p.x, p.y + 1, p.w, p.h)
  if p.ground and p.vy > 0 then
    p.vy = 0
    p.y = p.y // 1      -- drop the fraction gravity added
  end

  -- fell off the bottom of the screen: start again
  if p.y > 136 then
    p.x, p.y, p.vy =
      START_X, START_Y, 0
  end
end

function draw_player(p)
  local id
  if not p.ground then
    if p.vy < 0 then
      id = SPR_JUMP
    else
      id = SPR_FALL
    end
  elseif p.moving then
    id = anim_frame(ANIM_RUN, 6)
  else
    id = anim_frame(ANIM_IDLE, 30)
  end
  spr(id, p.x - 1, p.y, 0, 1, p.flip)
end

-- == Game loop ==
function TIC()
  t = t + 1
  update_player(player)

  cls(10)
  map(0, 0, 30, 17, 0, 0, 0)
  draw_player(player)
end

